   "descrizione": "Verifica il salvataggio dei dati in user:// e la funzione di rilevamento Web",
   "codice": "extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var save_script: GDScript = load("res://save_system.gd")
	if check("save_exists", save_script != null, "Lo script save_system.gd deve caricarsi senza errori"):
		var saver = save_script.new()
		if check("save_method", has_function(saver, "save_player_data"), "save_system.gd deve avere la funzione save_player_data()"):
			var ok: bool = call_if_exists(saver, "save_player_data", [{"score": 100}], false)
			check("save_ok", ok, "save_player_data() deve restituire true dopo il salvataggio")
			check("user_file_created", FileAccess.file_exists("user://player_data.json"), "Il file di dati deve essere creato in user://player_data.json")

	var web_script: GDScript = load("res://web_helper.gd")
	if check("web_exists", web_script != null, "Lo script web_helper.gd deve caricarsi senza errori"):
		var helper = web_script.new()
		if check("web_method", has_function(helper, "is_running_on_web"), "web_helper.gd deve avere la funzione is_running_on_web()"):
			var is_web: bool = call_if_exists(helper, "is_running_on_web", [], true)
			check("web_check_result", is_web == false, "is_running_on_web() deve restituire false quando eseguito nell'editor desktop")
"
  }
 ],
