func save_player_data(data: Dictionary) -> bool:
	# Percorso di salvataggio errato: res:// e in sola lettura nei giochi esportati
	var path := "res://player_data.json"
	var file := FileAccess.open(path, FileAccess.WRITE)
	if not file:
		return false
	file.store_string(JSON.stringify(data))
	file.close()
	return true
"
